baseCss:
.aha-pricing{
  container:aha-pricing / inline-size;
  position:relative;
  background:var(--aha-white);
  color:var(--aha-text-default);
  font-family:var(--aha-font-product);
}
.aha-pricing *{box-sizing:border-box}
:where(.aha-pricing) :is(h2,h3,p,ul,ol,figure,table){margin:0;padding:0}
:where(.aha-pricing) ul{list-style:none}
.aha-pricing__inner{max-width:80rem;margin:0 auto;padding:var(--aha-space-96) var(--aha-space-32)}
.aha-pricing__header{max-width:48rem;margin:0 0 var(--aha-space-40)}
.aha-pricing__header--center{margin-inline:auto;text-align:center}
.aha-pricing__eyebrow{margin:0 0 var(--aha-space-12);font-size:var(--aha-size-sm);font-weight:var(--aha-weight-semibold);letter-spacing:var(--aha-letter-spacing-subheadings);text-transform:uppercase;color:var(--aha-color-primary)}
.aha-pricing__title{font-family:var(--aha-font-display);font-size:var(--aha-size-h2);line-height:var(--aha-line-height-tight);font-weight:var(--aha-weight-semibold);letter-spacing:var(--aha-letter-spacing-headlines);color:var(--aha-text-default)}
.aha-pricing__lead{margin-top:var(--aha-space-20);font-size:var(--aha-size-xl);line-height:var(--aha-line-height-body);color:var(--aha-text-secondary)}
.aha-pricing__sr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
.aha-pricing__toggle-row{display:flex;justify-content:center;margin:0 0 var(--aha-space-48)}
.aha-pricing__toggle-row--start{justify-content:flex-start;margin-bottom:var(--aha-space-40)}
.aha-pricing__toggle{display:inline-flex;flex-wrap:wrap;align-items:center;gap:var(--aha-space-12)}
.aha-pricing__grid{display:grid;gap:var(--aha-space-32);align-items:stretch}
.aha-pricing__grid--3{grid-template-columns:repeat(3,minmax(0,1fr))}
.aha-pricing__grid--2{grid-template-columns:repeat(2,minmax(0,1fr))}
.aha-pricing__cell{position:relative;min-width:0}
.aha-pricing__split{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,2fr);gap:var(--aha-space-64);align-items:start}
.aha-pricing__split .aha-pricing__header{margin-bottom:var(--aha-space-32)}
.aha-pricing__items{display:flex;flex-direction:column;gap:var(--aha-space-24)}
.aha-pricing__item{display:flex;gap:var(--aha-space-16)}
.aha-pricing__item-icon{display:inline-flex;flex:none;align-items:center;justify-content:center;width:var(--aha-space-48);height:var(--aha-space-48);border:1px solid var(--aha-border-default);border-radius:var(--aha-radius-lg);background:var(--aha-white);color:var(--aha-icon-strong);box-shadow:0 var(--aha-space-2) var(--aha-space-4) var(--aha-ink-a10)}
.aha-pricing__item-title{font-size:var(--aha-size-l);font-weight:var(--aha-weight-semibold);color:var(--aha-text-default)}
.aha-pricing__item-text{margin-top:var(--aha-space-4);font-size:var(--aha-size-default);line-height:var(--aha-line-height-body);color:var(--aha-text-secondary)}
.aha-pricing__table-wrap{width:100%}
.aha-pricing__table{width:100%;border-collapse:separate;border-spacing:0;table-layout:fixed;text-align:center}
.aha-pricing__table caption{position:absolute}
.aha-pricing__plan-head{position:sticky;top:0;z-index:2;padding:var(--aha-space-24) var(--aha-space-16);background:var(--aha-white);vertical-align:top;font-weight:var(--aha-weight-regular)}
.aha-pricing__plan-head>*{display:block;margin-top:var(--aha-space-8)}
.aha-pricing__plan-head>:first-child{margin-top:0}
.aha-pricing__plan-head aha-tag{margin-left:var(--aha-space-8)}
.aha-pricing__plan-head>.aha-marketing-card__price{display:flex;justify-content:center}
.aha-pricing__plan-head .aha-marketing-card__text{font-size:var(--aha-size-default);line-height:var(--aha-line-height-body);color:var(--aha-text-secondary)}
.aha-pricing__plan-actions{margin-top:var(--aha-space-16)}
.aha-pricing__plan-actions .aha-marketing-card__button,.aha-pricing__foot-cell .aha-marketing-card__button{width:100%}
.aha-pricing__group th{padding:var(--aha-space-24) var(--aha-space-16) var(--aha-space-8);text-align:left;font-size:var(--aha-size-sm);font-weight:var(--aha-weight-semibold);letter-spacing:var(--aha-letter-spacing-subheadings);text-transform:uppercase;color:var(--aha-color-primary)}
.aha-pricing__table tbody tr:not(.aha-pricing__group) :is(th,td){padding:var(--aha-space-16);border-top:1px solid var(--aha-border-default);font-size:var(--aha-size-default);color:var(--aha-text-secondary);vertical-align:middle}
.aha-pricing__table tbody tr:not(.aha-pricing__group) th{text-align:left;font-weight:var(--aha-weight-semibold);color:var(--aha-text-default)}
.aha-pricing__table tbody tr:not(.aha-pricing__group):nth-child(even) :is(th,td){background:var(--aha-bg-container-secondary)}
.aha-pricing__table td aha-icon{color:var(--aha-color-primary)}
.aha-pricing__table td aha-icon[name="system-minus"]{color:var(--aha-icon-muted)}
.aha-pricing__foot-cell{padding:var(--aha-space-24) var(--aha-space-16);border-top:1px solid var(--aha-border-default)}
.aha-pricing__table .aha-pricing__col--featured{box-shadow:inset var(--aha-space-2) 0 0 var(--aha-color-primary),inset calc(-1 * var(--aha-space-2)) 0 0 var(--aha-color-primary)}
.aha-pricing__table thead .aha-pricing__col--featured{border-radius:var(--aha-radius-marketing) var(--aha-radius-marketing) 0 0;box-shadow:inset var(--aha-space-2) var(--aha-space-2) 0 var(--aha-color-primary),inset calc(-1 * var(--aha-space-2)) 0 0 var(--aha-color-primary)}
.aha-pricing__table .aha-pricing__col--last{border-radius:0 0 var(--aha-radius-marketing) var(--aha-radius-marketing);box-shadow:inset var(--aha-space-2) 0 0 var(--aha-color-primary),inset calc(-1 * var(--aha-space-2)) 0 0 var(--aha-color-primary),inset 0 calc(-1 * var(--aha-space-2)) 0 var(--aha-color-primary)}
.aha-pricing__slider{display:flex;align-items:center;gap:var(--aha-space-16);width:100%;margin:0 0 var(--aha-space-48)}
.aha-pricing__slider-label,.aha-pricing__slider-output{flex:none;font-size:var(--aha-size-default);font-weight:var(--aha-weight-semibold);color:var(--aha-text-default)}
.aha-pricing__slider-output{min-width:var(--aha-space-60);text-align:right}
.aha-pricing__slider-input{flex:1;min-width:0;accent-color:var(--aha-color-primary)}
.aha-pricing__slider-input:focus-visible{outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-4)}
.aha-pricing__styles{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--aha-space-48) var(--aha-space-32);align-items:start}
.aha-pricing__style{min-width:0}
.aha-pricing__style--wide{grid-column:span 2}
.aha-pricing__style-label{display:flex;flex-direction:column;gap:var(--aha-space-2);margin:0 0 var(--aha-space-12);font-size:var(--aha-size-default);color:var(--aha-text-default)}
.aha-pricing__style-label span{color:var(--aha-text-tertiary)}
.aha-pricing__style-stage{position:relative;isolation:isolate;padding:var(--aha-space-24);border-radius:var(--aha-radius-marketing)}
.aha-pricing__style-stage--callout{padding-top:var(--aha-space-48)}
.aha-pricing__style-stage--angles{background:var(--aha-vivid-pink-5);overflow:hidden}
.aha-pricing__style-stage--angles::before{content:"";position:absolute;inset:0;z-index:-1;background:var(--aha-vivid-pink-30);clip-path:polygon(0 62%,100% 22%,100% 46%,0 100%)}
.aha-pricing__style-stage--band{background:var(--aha-color-primary)}
@container aha-pricing (max-width:991px){
  .aha-pricing__inner{padding:var(--aha-space-80) var(--aha-space-24)}
  .aha-pricing__title{font-size:var(--aha-size-h3)}
  .aha-pricing__grid--3{grid-template-columns:minmax(0,1fr)}
  .aha-pricing__split{grid-template-columns:minmax(0,1fr);gap:var(--aha-space-32)}
  .aha-pricing__styles{grid-template-columns:repeat(2,minmax(0,1fr))}
  .aha-pricing__style--wide{grid-column:span 2}
}
@container aha-pricing (max-width:767px){
  .aha-pricing__inner{padding:var(--aha-space-64) var(--aha-space-20)}
  .aha-pricing__lead{font-size:var(--aha-size-l)}
  .aha-pricing__grid--2{grid-template-columns:minmax(0,1fr)}
  .aha-pricing__styles{grid-template-columns:minmax(0,1fr)}
  .aha-pricing__style--wide{grid-column:auto}
  .aha-pricing__table,.aha-pricing__table thead,.aha-pricing__table tbody,.aha-pricing__table tfoot,.aha-pricing__table tr,.aha-pricing__table th,.aha-pricing__table td{display:block}
  .aha-pricing__corner{display:none}
  .aha-pricing__table thead tr{display:flex;flex-direction:column;gap:var(--aha-space-16)}
  .aha-pricing__plan-head{position:static;padding:var(--aha-space-24);border:1px solid var(--aha-border-default);border-radius:var(--aha-radius-marketing);text-align:left}
  .aha-pricing__plan-head>.aha-marketing-card__price{justify-content:flex-start}
  .aha-pricing__table tbody tr:not(.aha-pricing__group){padding:var(--aha-space-12) 0;border-top:1px solid var(--aha-border-default)}
  .aha-pricing__table tbody tr:not(.aha-pricing__group) :is(th,td){display:flex;align-items:center;justify-content:space-between;gap:var(--aha-space-12);padding:var(--aha-space-4) var(--aha-space-8);border-top:0;background:transparent !important;text-align:left}
  .aha-pricing__table tbody tr:not(.aha-pricing__group) th{padding-bottom:var(--aha-space-8)}
  .aha-pricing__table td[data-plan]::before{content:attr(data-plan);color:var(--aha-text-secondary)}
  .aha-pricing__table .aha-pricing__col--featured,.aha-pricing__table .aha-pricing__col--last,.aha-pricing__table thead .aha-pricing__col--featured{border-radius:0;box-shadow:none}
  .aha-pricing__table thead .aha-pricing__col--featured{border-color:var(--aha-color-primary);box-shadow:0 0 0 1px var(--aha-color-primary);border-radius:var(--aha-radius-marketing)}
  .aha-pricing__table tfoot{display:none}
  .aha-pricing__slider{flex-wrap:wrap}
}
